import{_ as c,r as n,o as i,c as r,e as s,a as e,d as a,s as p}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Content Blocks - October CMS - 4.x","titleTemplate":false,"description":"Dedicated files for storing and updating page content.","frontmatter":{"subtitle":"Dedicated files for storing and updating page content."},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Rendering Content Blocks","slug":"rendering-content-blocks","link":"#rendering-content-blocks","children":[]},{"level":2,"title":"Translating Content Blocks","slug":"translating-content-blocks","link":"#translating-content-blocks","children":[]},{"level":2,"title":"Passing Variables to Content Blocks","slug":"passing-variables-to-content-blocks","link":"#passing-variables-to-content-blocks","children":[{"level":3,"title":"Global Variables","slug":"global-variables","link":"#global-variables","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/cms/themes/content.md","filePath":"4.x/cms/themes/content.md"}'),d={name:"4.x/cms/themes/content.md"};function g(h,t,u,k,m,b){const o=n("pre-heading"),l=n("post-heading");return i(),r("div",null,[s(o),t[0]||(t[0]=e("h1",null,"Content Blocks",-1)),s(l),t[1]||(t[1]=e("p",null,[a("Content Blocks can be text, HTML or "),e("a",{href:"http://daringfireball.net/projects/markdown/syntax",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Markdown"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),e("span",{class:"sr-only"},"(opens new window)")])]),a(" blocks that are edited separately from the page or layout. They're designed to hold static content only and support basic templating variables. "),e("a",{href:"./partials.html"},"Partials"),a(" are more flexible and should be used for generating dynamic content.")],-1)),t[2]||(t[2]=p(`<h2 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h2><p>Content blocks files reside in the <strong>/content</strong> subdirectory of a theme directory. The following extensions are supported for content files.</p><div class="table"><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><strong>html</strong></td><td>Used for HTML markup (WYSIWYG editor).</td></tr><tr><td><strong>htm</strong></td><td>Used for HTML markup (code editor).</td></tr><tr><td><strong>txt</strong></td><td>Used for plain text.</td></tr><tr><td><strong>md</strong></td><td>Used for Markdown syntax.</td></tr></tbody></table></div><p>The extension affects a content block&#39;s display mode in the back-end user interface, either with a WYSIWYG editor, code editor or markdown editor. It also determines rendering the blocks on the website; for example, Markdown blocks will convert to HTML before display.</p><h2 id="rendering-content-blocks"><a href="#rendering-content-blocks" class="header-anchor">#</a> Rendering Content Blocks</h2><p>Use the <code>{% content &#39;file.htm&#39; %}</code> tag to render a content block in a <a href="./pages.html">page</a>, <a href="./partials.html">partial</a> or <a href="./layouts.html">layout</a>.</p><p>This example shows a complete page rendering a content block.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contacts</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contacts<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>contacts.html<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Another example rendering some markdown with the <code>md</code> extension.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>my-markdown.md<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="translating-content-blocks"><a href="#translating-content-blocks" class="header-anchor">#</a> Translating Content Blocks</h2><p>When using <a href="./../multisite/multisite.html">site definitions</a> with different locales, a content block is translated by placing a copy of the file inside a subdirectory named after the locale. The base file acts as the default and the locale directory mirrors the same file path.</p><div class="language- extra-class"><pre class="language-text"><code>content/
├── my-content.htm          ← Default locale
├── fr/
│   └── my-content.htm      ← French
└── ru/
    └── my-content.htm      ← Russian
</code></pre></div><p>Nested paths mirror the same way, so <code>content/blog/intro.htm</code> translates as <code>content/fr/blog/intro.htm</code>, where the locale directory is created at the content root.</p><p>When the block is rendered, the directories are checked against the active site&#39;s locale in the following order, where the first matching file wins.</p><ol><li>The exact site locale, for example <code>fr-ca</code>.</li><li>The base language of the locale, for example <code>fr</code>.</li><li>The base file.</li></ol><p>This means a site using the <code>fr-ca</code> locale shares the <code>fr</code> directory until a dedicated <code>fr-ca</code> directory exists, and any site without a matching directory falls back to the base file. The lookup only applies to directories matching the active site&#39;s locale, so directories with other names remain addressable directly, for example <code>{% content &#39;fr/my-content.htm&#39; %}</code>.</p><h2 id="passing-variables-to-content-blocks"><a href="#passing-variables-to-content-blocks" class="header-anchor">#</a> Passing Variables to Content Blocks</h2><p>Sometimes you may need to pass variables to a content block from the external code. While content blocks do not support Twig markup, they do support using variables with basic syntax. You can pass variables to content blocks by specifying them after the content block name in the <code>{% content %}</code> tag.</p><p>Passing the variable called <code>name</code> with a value <strong>John</strong> to the content block.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> name<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>John<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Inside the content block, variables can be accessed using singular <em>curly brackets</em>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>This is a demo for {name}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>More information on variable use can be found in the <a href="./../../markup/tag/content.html">Markup guide</a>.</p></div><h3 id="global-variables"><a href="#global-variables" class="header-anchor">#</a> Global Variables</h3><p>You may register variables that are globally available to all content blocks with the <code>View::share</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>A common area to place this method is inside the register or boot method of a <a href="./../../extend/system/plugins.html">plugin registration file</a>. Using the above example, the variable <code>{site_name}</code> will be available inside all content blocks.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Welcome to {site_name}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/content.html">Content Twig Tag</a></li></ul></div>`,31))])}const w=c(d,[["render",g]]);export{v as __pageData,w as default};
